SELECT 
FROM llm_config
WHERE user_id = #{userId}
  AND capability_type = #{capabilityType}
  AND deleted = 0
ORDER BY priority ASC, id ASC

mapper.update:
UPDATE llm_config
SET is_default = FALSE, updated_at = NOW()
WHERE user_id = #{userId}
  AND capability_type = #{capabilityType}
  AND is_default = TRUE
  AND deleted = 0
  AND id != #{excludeId}
